import {summaryMarkup,editProposalInput,collectEditedProposal,summaryNeedsRefresh} from './proposal-summary.js';
import {installSetupAgent,applyAgentProposal,proposalInput} from './setup-agent.js';
import {fetchPackIndex} from './packs.js';
import {episodeDates} from './m2c.js';
import {SimulationLibrary,studioURL,simulationYears} from './simulation-library.js';
import {wizardDraft,stageMarkup,installStageControls,applyRegion,setupProposal,acceptSetup,goalMarkup,kpiMarkup,selectedGoals,mergeValues} from './setup-config.js';
import {fetchKpiCatalogue,kpisForGoals} from './kpis.js';
import {servedServices} from './schema-form.js';
import {GAS_PATH,servicesState,servicesSummary,staffingSummary,staffingBase} from './setup-utility.js';
import {installShareFiles,handleLabel} from './share-file.js';
import {isApp,localRequest} from './local-session.js';
import {installGuidedSetup,worldRequest} from './guided-setup.js';
import {newMetrics,metricsMarkup,bindMetrics,fitMetrics,metricReportMarkup} from './twin-setup.js';
import {installEngineMonitor} from './engine-monitor.js';
installEngineMonitor();

const root=document.getElementById('setup-root'),query=new URLSearchParams(location.search);
const api=(query.get('engine')||'').replace(/\/$/,'')+'/api';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const steps=['Starting point','Your focus','Environment','Utility & operations','Review & open'];
const localNote='Saved in this browser. Use the same browser to return to your simulations.';
const TRASH='<svg viewBox="0 0 24 24" width="16" height="16" aria-hidden="true" focusable="false" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><path d="M4 7h16M10 11v6M14 11v6M5.5 7l.9 12.1A2 2 0 0 0 8.4 21h7.2a2 2 0 0 0 2-1.9L18.5 7M9 7V4.5A1.5 1.5 0 0 1 10.5 3h3A1.5 1.5 0 0 1 15 4.5V7"/></svg>';
const configs=new Map();
let library,packs,files,kpiCatalogue=null,twinDictionary=null,draft,step=0,scenarios=[],scenarioState='idle',message='',configError='',agentOpen=false,closeAgent=null,stageControls=null,busy=false;
function alertMessage(text){const el=document.getElementById('setup-message');if(el){el.textContent=text;el.focus();}}
function save(){draft=library.save({...draft,step,wizardVersion:4});}
function capture(){if(!draft)return;for(const key of ['name','purpose','region','asOf','seed']){const input=document.getElementById('setup-'+key);if(input)draft[key]=input.value.trim();}}
function changed(dirty=true){capture();if(dirty){draft.configDirty=true;draft.agentSummaryDirty=!!draft.agentProposal;if(draft.agent)draft.agent.proposal=null;}try{save();}catch(e){alertMessage(e.message);}}
function showLibrary(){closeAgent?.();closeAgent=null;agentOpen=false;draft=null;message='';history.replaceState(null,'',location.pathname+location.search+'#/simulations');const list=library.list();
 root.innerHTML=`<section class="library"><div class="eyebrow">YOUR WORKSPACE</div><div class="library-heading"><div><h1>Your simulations</h1><p>Pick up an existing simulation, or start with a new question.</p></div><div class="library-actions"><button class="secondary" id="import-file">Import simulation</button><button class="primary" id="new-simulation">＋ New simulation</button></div></div><p class="storage-note">${localNote} Setup and analyst actions are remembered; live views are recalculated when opened.</p><p id="setup-message" role="alert" tabindex="-1"></p><div class="simulation-grid">${list.map(s=>`<article class="simulation-card" data-card="${esc(s.id)}"><div class="card-top"><span class="status ${s.status}${s.locked===false?' unlocked':''}">${s.status==='draft'?'SETUP IN PROGRESS':s.locked===false?'READY TO START':'SAVED SIMULATION'}</span><span class="card-top-end">${s.handle?`<span class="card-handle" title="This simulation’s file name">${esc(handleLabel(s.handle))}</span>`:''}<span title="Years opened">${esc(simulationYears(s,library.storage).label)}</span><button type="button" class="card-delete" data-delete="${esc(s.id)}" aria-label="Delete ${esc(s.name||'Untitled simulation')}" aria-expanded="false" title="Delete">${TRASH}</button></span></div><h2>${esc(s.name||'Untitled simulation')}</h2><p>${esc(s.purpose||s.scenarioTitle||'Normal operations')}</p><dl><div><dt>Town</dt><dd>${esc(s.townName||'Not selected')}</dd></div><div><dt>Homes</dt><dd>${s.homes?Number(s.homes).toLocaleString('en-CA'):'—'}</dd></div><div><dt>View date</dt><dd>${esc(s.asOf||'—')}</dd></div></dl><button class="${s.status==='draft'?'secondary':'primary'}" data-open="${esc(s.id)}">${s.status==='draft'?'Continue setup':s.locked===false?'Review & start':'Open simulation'} <span aria-hidden="true">→</span></button>${s.status==='draft'?'':`<button type="button" class="text-button card-code" data-export="${esc(s.id)}">Export</button>`}<div class="card-confirm" role="group" aria-label="Confirm deleting ${esc(s.name||'Untitled simulation')}" hidden><p>Delete this simulation?</p><span>Its settings and analyst actions in this browser go too.</span><button type="button" class="danger" data-confirm-delete="${esc(s.id)}">Delete</button><button type="button" class="secondary" data-cancel-delete>Cancel</button></div></article>`).join('')}</div><aside class="archive-note"><strong>Already have downloaded results?</strong><p>Open a saved run to browse its results without recalculating.</p><a href="./runs.html">Open a run folder →</a></aside></section>`;
 document.getElementById('new-simulation').onclick=()=>begin();document.getElementById('import-file').onclick=()=>files.importSimulation();
 root.querySelectorAll('[data-export]').forEach(b=>b.onclick=async()=>{try{const s=library.get(b.dataset.export);if(!s)throw Error('Simulation not found in this browser.');if(await files.exportSimulation(s))showLibrary();}catch(e){alertMessage(e.message);}});
 root.querySelectorAll('[data-open]').forEach(b=>b.onclick=()=>{try{const s=library.get(b.dataset.open);if(!s)throw Error('Simulation not found in this browser.');if(s.status==='draft')begin(s);else open(s);}catch(e){alertMessage(e.message);}});
 // Delete: the bin opens a small confirm inside the card; Cancel or Escape closes it and returns to the bin.
 const confirming=(card,on)=>{card.classList.toggle('is-confirming',on);card.querySelector('.card-confirm').hidden=!on;card.querySelector('[data-open]').hidden=on;card.querySelector('.card-delete').setAttribute('aria-expanded',String(on));(on?card.querySelector('[data-cancel-delete]'):card.querySelector('.card-delete')).focus();};
 root.querySelectorAll('[data-card]').forEach(card=>{card.querySelector('.card-delete').onclick=()=>{for(const other of root.querySelectorAll('.simulation-card.is-confirming'))if(other!==card)confirming(other,false);confirming(card,!card.classList.contains('is-confirming'));};
  card.querySelector('[data-cancel-delete]').onclick=()=>confirming(card,false);card.onkeydown=e=>{if(e.key==='Escape'&&card.classList.contains('is-confirming'))confirming(card,false);};
  card.querySelector('[data-confirm-delete]').onclick=()=>{const id=card.dataset.card,name=card.querySelector('h2').textContent;try{library.remove(id);}catch(e){alertMessage(e.message);return;}if(!library.list().length){begin();return;}showLibrary();alertMessage(`Deleted “${name}”.`);};});
}
function begin(s){agentOpen=false;configError='';draft=wizardDraft(s||library.create(),packs);if(!s){draft.guidedSetup={version:1,page:'identity',pace:'quick',mode:isApp()?'world':'studio',pins:{},choices:{},suggestions:{}};draft.asOf='2026-01-01';}if(draft.guidedSetup)draft.guidedSetup.review=null;step=draft.step||0;message='';history.replaceState(null,'',location.pathname+location.search+'#/setup/'+encodeURIComponent(draft.id));render();loadConfiguration();loadScenarios();loadKpis();loadTwinDictionary();}
async function loadConfiguration(){const preset=draft?.preset;if(!preset){configError='The town catalogue could not load. Refresh to try again.';render(false);return;}if(configs.has(preset))return;
 configError='';try{const r=await fetch(api+'/setup/configuration?preset='+encodeURIComponent(preset),{signal:AbortSignal.timeout(15000)});const data=await r.json();if(!r.ok)throw Error(typeof data.detail==='string'?data.detail:'Setup settings are unavailable.');configs.set(preset,data);}catch(e){configError='Could not load setup settings. '+(e.name==='TimeoutError'?'The engine took too long.':e.message);}
 if(draft?.preset===preset&&!agentOpen)render(false);
}
async function loadKpis(){if(kpiCatalogue)return;try{kpiCatalogue=await fetchKpiCatalogue(api);}catch{return;}if(draft&&step===1&&!agentOpen)render(false);}
async function loadScenarios(){if(scenarioState==='loading'||scenarioState==='ready')return;scenarioState='loading';try{const r=await fetch(api+'/m2c/scenarios',{signal:AbortSignal.timeout(12000)});const data=await r.json();if(!r.ok||!Array.isArray(data.scenarios))throw Error();scenarios=data.scenarios;scenarioState='ready';}catch{scenarioState='failed';}if(draft&&step===3&&!agentOpen)bindScenarios();}
const starters=[['baseline','Normal operations','The usual day-to-day.'],['starter_busy','A little busy','A few more hiccups.'],['starter_pressure','Under pressure','A stretched team and rising queues.'],['starter_chaos','Organised chaos','Several things go wrong together.']];
function scenarioChoices(){return [...(draft.scenarioId==='custom'?[{id:'custom',title:draft.scenarioTitle,description:draft.summary||'Your reviewed scenario.'}]:[]),{id:'baseline',title:'Normal operations',description:'Your chosen staffing and workflow form the baseline. Add dated changes in the Command Center.'},...scenarios.filter(s=>s.id===draft.scenarioId||draft.goals?.includes('everything')||s.id.startsWith('starter_')||s.episodes.some(ep=>Object.keys(ep.settings).some(k=>selectedGoals(configs.get(draft.preset),draft).some(g=>g.run.includes(k)))))];}
function bindScenarios(){const box=root.querySelector('#scenario-controls');if(!box)return;if(draft.goals?.length===1&&draft.goals[0]==='operations'){box.innerHTML='<p class="field-note">Use the map to inflict incidents and dispatch crews. Map-day settings above control this experiment. Year scenarios remain available from the Command Center.</p>';return;}box.innerHTML=`<fieldset class="starter-choices"><legend>How should the year begin?</legend>${starters.map(([id,title,note],i)=>{const available=id==='baseline'||scenarios.some(s=>s.id===id);return `<label class="starter-choice ${draft.scenarioId===id?'selected':''}"><input type="radio" name="starter" value="${id}" ${draft.scenarioId===id?'checked':''} ${available?'':'disabled'}><span><small>${'●'.repeat(i+1)}${'○'.repeat(3-i)}</small><strong>${title}</strong><span>${note}</span></span></label>`;}).join('')}</fieldset><label for="setup-scenario">Or choose a specific scenario</label><select id="setup-scenario">${scenarioChoices().map(s=>`<option value="${esc(s.id)}" ${draft.scenarioId===s.id?'selected':''}>${esc(s.title)}</option>`).join('')}</select><p class="field-note">${esc(scenarioChoices().find(s=>s.id===draft.scenarioId)?.description||draft.scenarioTitle)}</p>${scenarioState==='failed'?'<p class="field-note">Extra scenarios are unavailable. Normal operations is available.</p><button type="button" id="retry-scenarios" class="text-button">Retry scenarios</button>':scenarioState!=='ready'?'<p class="field-note" role="status">Loading scenarios…</p>':''}`;
 const choose=id=>{const s=scenarioChoices().find(s=>s.id===id);if(!s)return;draft.scenarioId=s.id;draft.scenarioTitle=s.title;if(id!=='custom')draft.episodes=id==='baseline'?[]:episodeDates(s,'2026-01-01').map((ep,i)=>({...ep,id:'EP-'+(i+1)}));changed();bindScenarios();};
 box.querySelector('#setup-scenario').onchange=e=>choose(e.target.value);box.querySelectorAll('[name="starter"]').forEach(i=>i.onchange=()=>choose(i.value));const retry=box.querySelector('#retry-scenarios');if(retry)retry.onclick=()=>{scenarioState='idle';loadScenarios();};
}
async function checked(proposal){if(isApp())proposal={...proposal,execution:'local',totalHomes:proposal.totalHomes||proposal.townOverrides?.town?.houses||draft?.homes||500};const r=await fetch(api+'/setup-agent/validate',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(proposalInput(proposal)),signal:AbortSignal.timeout(20000)});const data=await r.json();if(!r.ok)throw Error(typeof data.detail==='string'?data.detail:Array.isArray(data.detail)?data.detail.map(e=>e.loc.slice(1).join('.')+': '+e.msg).join('; '):'These inputs could not be accepted. Check the values.');return data.proposal;}
function lock(){busy=true;root.querySelectorAll('button,input,select,textarea').forEach(e=>e.disabled=true);alertMessage('Checking your settings…');}
async function advance(){if(busy)return;capture();if(step===0){draft.name||=draft.setupPath==='metrics'?'My utility twin':'My utility';draft.setupPath||='build';draft.metricDraft||=newMetrics();step=1;save();render();return;}if(!draft.name.trim()){alertMessage('Give your simulation a name.');return;}if(step===1&&draft.setupPath==='metrics'){lock();try{const result=await fitMetrics(draft,twinDictionary,{api,onProgress:alertMessage});draft=acceptSetup(draft,await checked(result.proposal));draft.metricReport=result.report;draft.setupPath='metrics';draft.scenarioId='custom';draft.scenarioTitle='Your KPI history and targets';step=2;save();message='The engine fitted your observations. Review the environment and staffing it proposed.';}catch(e){message=e.message;}finally{busy=false;}render();loadConfiguration();return;}if(step===1){if(!draft.goals?.length){alertMessage('Choose at least one area to test.');return;}step=2;save();render();return;}if(step>1&&step<4&&stageControls?.invalid()){alertMessage('Fix the highlighted settings before continuing.');root.querySelector('[aria-invalid="true"]')?.focus();return;}if(step===4&&(draft.agentSummaryDirty||draft.configDirty)){alertMessage('Recheck the edited inputs before opening.');return;}
 lock();try{draft=acceptSetup(draft,await checked(setupProposal(draft)));if(step===4){draft.status='ready';draft.locked=draft.execution!=='local';save();open(draft);return;}step++;message='';save();}catch(e){message=e.message;}finally{busy=false;}render();
}
function reviewMarkup(){const local=draft.execution==='local',p=local&&draft.agentProposal?{...draft.agentProposal,changes:draft.agentProposal.changes?.map(c=>c.scope==='town'&&c.path==='town.houses'?{...c,title:'District template · Houses',readOnly:true,impact:'Utility Studio divides your selected total into checkpoints of up to 10,000 homes. Change the total with the Environment town-size buttons.'}:c)}:draft.agentProposal,data=configs.get(draft.preset),at=(o,path)=>path.split('.').reduce((v,k)=>v?.[k],o);
 const town=mergeValues(data?.defaults.town,draft.townOverrides),services=servicesState({served:servedServices(town),share:at(town,GAS_PATH),homes:draft.homes,gasMinHomes:data?.gasDistrictMinHomes});
 return `${metricReportMarkup(draft.metricReport||draft.metricHistory)}<div class="review-name">${esc(draft.name)}</div>${draft.purpose?`<p>${esc(draft.purpose)}</p>`:''}<dl class="review"><div><dt>Test focus</dt><dd>${selectedGoals(configs.get(draft.preset),draft).map(g=>esc(g.title)).join(', ')}</dd></div><div><dt>Environment</dt><dd>${esc(draft.region||draft.townName)} · ${Number(draft.homes).toLocaleString('en-CA')} homes</dd></div><div><dt>Services</dt><dd>${esc(servicesSummary(services))}</dd></div><div><dt>Staffing${local?' per district':''}</dt><dd>${esc(staffingSummary(draft.settings,staffingBase(data?.defaults.run)))}</dd></div><div><dt>Starting scenario</dt><dd>${esc(draft.scenarioTitle)}</dd></div><div><dt>Open at</dt><dd>${esc(draft.asOf)} · model year 2026</dd></div><div><dt>Run seed</dt><dd>${esc(draft.seed||'Town default')}</dd></div>${draft.kpis?.length?`<div><dt>Watching</dt><dd>${draft.kpis.map(id=>esc(kpiCatalogue?.kpis?.find(k=>k.id===id)?.title||id)).join(' · ')}</dd></div>`:''}</dl><div class="review-edit-links"><button class="text-button" type="button" data-edit-stage="1">Edit test goals</button><button class="text-button" type="button" data-edit-stage="2">Edit environment</button><button class="text-button" type="button" data-edit-stage="3">Edit utility & operations</button><button class="text-button" id="open-agent" type="button">Refine with Claude</button></div>${local?'<p class="field-note">The total above is processed in internal checkpoints of up to 10,000 homes. Your Command Center combines all records and results. The environment settings apply to every district; staffing numbers above are per district.</p>':''}${p?`${summaryMarkup(p,{dirty:draft.agentSummaryDirty||draft.configDirty})}<details><summary>Assumptions and model limits</summary><ul>${[...p.assumptions,...p.limitations].map(t=>`<li>${esc(t)}</li>`).join('')}</ul></details>`:''}${local?'<div class="help-card"><strong>Next: run it on this computer.</strong><p>The run page queues the first revision in Utility Studio; the full results stay in your storage folder. You can edit the setup or inflict a scenario later; each change makes a new revision and keeps the previous results.</p></div>':`<div class="help-card"><strong>Next: explore your utility.</strong><p>The full Config page opens with every setting for this simulation. Check them, then lock them in to start the simulation in ${draft.goals?.length===1&&draft.goals[0]==='operations'?'the operations map':'the Command Center'}. Use the Command Center to apply dated changes during the year.</p></div>`}`;}
function render(focus=true){if(!draft)return;if(summaryNeedsRefresh(draft.agentProposal))draft.agentSummaryDirty=true;closeAgent?.();closeAgent=null;stageControls=null;
 if(agentOpen){root.innerHTML='<section class="wizard agent-wizard"><aside class="wizard-rail"><div class="eyebrow">CONVERSATIONAL SETUP</div><h2>Your environment.<br>Your utility.</h2><p>Start with what to test, then focus on the environment and operations that matter.</p><div class="rail-foot">You review every input before opening the Command Center.</div></aside><section class="wizard-panel" id="agent-root"></section></section>';
  closeAgent=installSetupAgent({root:document.getElementById('agent-root'),api,getDraft:()=>draft,onSave:agent=>{draft.agent=agent;draft.name||='Untitled simulation';save();},onApply:p=>{draft=applyAgentProposal(draft,p);draft.environmentProfile='custom';draft.agentSummaryDirty=false;draft.configDirty=false;step=4;save();agentOpen=false;render();loadConfiguration();},onBack:()=>{agentOpen=false;render();loadConfiguration();}});return;}
 if(draft.setupPath!=='metrics'){
  installGuidedSetup({root,data:configs.get(draft.preset),draft,local:isApp(),focus,error:configError,onRetry:loadConfiguration,
   onSave:updated=>{draft=updated;save();},onLibrary:showLibrary,onAgent:()=>{agentOpen=true;render();},
   onMetrics:()=>{draft.setupPath='metrics';draft.metricDraft||=newMetrics();step=1;save();render();},
   onFinish:async(updated,{create})=>{
    draft=updated;
    if(draft.guidedSetup.mode==='world'){
     const request=worldRequest(draft,configs.get(draft.preset));save();
     if(!create){await localRequest('worlds/setup/validate',request);return;}
     const world=await localRequest('worlds/setup/create',request,{timeout:600000});
     Object.assign(updated,{worldId:world.id,status:'ready',locked:true,townName:updated.region||updated.name});draft=updated;save();open(draft);return true;
    }else{
     // Validate again at the final boundary, including dependencies across pages and any imported episodes.
     Object.assign(draft,acceptSetup(draft,await checked(setupProposal(draft))));
     if(create){delete draft.worldId;draft.status='ready';draft.locked=draft.execution!=='local';save();open(draft);return true;}
    }
   }});return;
 }
 const data=configs.get(draft.preset),agentEntry='<aside class="agent-entry"><div><strong>Prefer to talk it through?</strong><p>Describe the question you want to answer. Claude can help choose the relevant settings.</p></div><button class="secondary" type="button" id="open-agent">Talk it through →</button></aside>';
 const configPart=configError?`<p class="inline-error">${esc(configError)}</p><button type="button" class="secondary" id="retry-config">Retry settings</button>`:`<p class="focus-note">Focus: ${selectedGoals(data,draft).map(g=>esc(g.title)).join(', ')||'Choose what to test first'}. Advanced includes the relevant settings and an option to show everything.</p>${stageMarkup(step-2,data,draft)}`;
 const start=`<div class="setup-paths"><button type="button" class="setup-path ${draft.setupPath!=='metrics'?'selected':''}" data-setup-path="build" aria-pressed="${draft.setupPath!=='metrics'}"><span class="path-symbol">⌂</span><strong>Build from the ground up</strong><span>Shape a place, choose your services and teams, then explore what happens.</span><small>Settings → simulated outcomes</small></button><button type="button" class="setup-path ${draft.setupPath==='metrics'?'selected':''}" data-setup-path="metrics" aria-pressed="${draft.setupPath==='metrics'}"><span class="path-symbol">↗</span><strong>Match existing metrics</strong><span>Start with where your KPIs were, where they went, and where they need to be.</span><small>Observed outcomes → a fitted utility</small></button></div><label for="setup-name">Simulation name</label><input id="setup-name" value="${esc(draft.name)}" maxlength="100" placeholder="My utility"><p class="path-footnote">Both paths lead to the same editable Command Center. You can change the year as you explore.</p>`;
 const content=step===0?start:step===1&&draft.setupPath==='metrics'?metricsMarkup(draft,twinDictionary):step===1?`${agentEntry}<label for="setup-name">Simulation name</label><input id="setup-name" value="${esc(draft.name)}" maxlength="100" placeholder="e.g. Can our VEE team handle a busier winter?" required autocomplete="off">${data?goalMarkup(data,draft)+kpiMarkup(kpiCatalogue,draft):configPart}<label for="setup-purpose">What would a useful result tell you? <span>Optional</span></label><textarea id="setup-purpose" maxlength="500" rows="2" placeholder="e.g. How many analysts do we need to clear the backlog?">${esc(draft.purpose)}</textarea>`:step===2?`${agentEntry}${configPart}`:step===3?`${agentEntry}${configPart}<div class="setup-section"><div id="scenario-controls"></div><label for="setup-asOf">Open at this date</label><input id="setup-asOf" type="date" min="2026-01-01" max="2026-12-31" value="${esc(draft.asOf)}" required><p class="field-note">The model starts January 1, 2026. Starting scenarios add dated changes to the baseline you chose above.</p><details><summary>Repeatability</summary><label for="setup-seed">Run seed <span>Optional</span></label><input id="setup-seed" maxlength="64" value="${esc(draft.seed)}" placeholder="Use the town’s seed"><p class="field-note">The environment’s master seed shapes the town. This optional seed re-rolls the utility year.</p></details></div>`:reviewMarkup();
 const headings=['Where would you like to start?',draft.setupPath==='metrics'?'Recreate the story in your numbers.':'What do we really want to test?','Build the environment.','Set up your utility.','Your simulation, ready to open.'];
 const intros=['Build a new utility or begin with the results of an existing one.',draft.setupPath==='metrics'?'Start with the changes you observed and the outcome you want to reach.':'Choose your experiment. We’ll tailor the next pages to the parts of the engine you care about.','Choose the size and regional character of the place you want to model.','Choose services, staffing and how the year begins.','Review what each input changes. Edit a value here or return to either setup stage.'];
 root.innerHTML=`<div class="wizard"><aside class="wizard-rail"><div class="eyebrow">NEW SIMULATION</div><h2>A place.<br>A utility.<br>A year to explore.</h2><p>Start with the essentials. Open Advanced whenever you want more control.</p><ol>${steps.map((title,i)=>`<li class="${i===step?'current':i<step?'complete':''}" ${i===step?'aria-current="step"':''}><span>${i<step?'✓':i+1}</span>${i===1&&draft.setupPath==='metrics'?'Your metrics':title}</li>`).join('')}</ol><div class="rail-foot">Your setup is saved as you go.<br>No account needed.</div></aside><section class="wizard-panel"><div class="wizard-top"><span>STEP ${step+1} OF 5</span><button class="text-button" type="button" id="show-library">My simulations</button></div><h1 tabindex="-1">${headings[step]}</h1><p class="intro">${intros[step]}</p><form id="setup-form">${content}<p id="setup-message" role="alert" tabindex="-1">${esc(message)}</p><div class="wizard-actions"><button class="secondary" id="previous" type="button" ${step===0?'hidden':''}>← Back</button><span></span><button class="primary" type="submit" ${step>0&&step<4&&!data?'disabled':''}>${step===4?'Open Command Center':step===0?'Continue':step===1?(draft.setupPath==='metrics'?'Fit my metrics':'Choose environment'):step===2?'Continue to utility':'Review setup'} <span aria-hidden="true">→</span></button></div></form><p class="storage-note">${localNote}</p></section></div>`;
 if(step>1&&step<4&&data&&!configError)stageControls=installStageControls({root,stage:step-2,data,getDraft:()=>draft,onChange:changed,onShowAll:show=>{(draft.showAllSettings||={})[step-2]=show;save();render(false);},onError:alertMessage,getOperationDefaults:async()=>{const r=await fetch(api+'/setup/operation-defaults',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({name:'Setup defaults',summary:'Resolve inherited map settings',preset:draft.preset,townOverrides:draft.townOverrides}),signal:AbortSignal.timeout(15000)});const result=await r.json();if(!r.ok)throw Error(typeof result.detail==='string'?result.detail:'Check the town settings.');return result.defaults;},onRegion:region=>{capture();draft=region?applyRegion(draft,region):{...draft,environmentProfile:'custom'};root.querySelector('#setup-region').value=draft.region||'';changed();render(false);}});
 root.querySelectorAll('[data-setup-path]').forEach(b=>b.onclick=()=>{capture();draft.setupPath=b.dataset.setupPath;draft.metricDraft||=newMetrics();save();render(false);});
 if(step===1&&draft.setupPath==='metrics')bindMetrics(root,draft,{save,dictionary:twinDictionary,render:()=>render(false)});
 root.querySelectorAll('[name="test-goal"]').forEach(input=>input.onchange=()=>{const goals=new Set(draft.goals||[]);if(input.checked){if(input.value==='everything')goals.clear();else goals.delete('everything');goals.add(input.value);}else goals.delete(input.value);draft.goals=[...goals];draft.showAllSettings={};if(kpiCatalogue){const allowed=new Set(kpisForGoals(kpiCatalogue,draft.goals).map(k=>k.id));draft.kpis=(draft.kpis||[]).filter(id=>allowed.has(id));}changed();root.querySelectorAll('[name="test-goal"]').forEach(i=>i.checked=goals.has(i.value));const box=root.querySelector('.kpi-picker');if(box&&kpiCatalogue){box.outerHTML=kpiMarkup(kpiCatalogue,draft);bindKpis();}});
 bindKpis();
 if(step===3)bindScenarios();
 if(focus)root.querySelector('h1').focus();
 const submit=root.querySelector('#setup-form button[type="submit"]');if(step===4)submit.disabled=!!(draft.agentSummaryDirty||draft.configDirty);
 const summaryCheck=root.querySelector('[data-summary-recheck]');if(summaryCheck){root.querySelectorAll('[data-summary-change]').forEach(input=>input.oninput=()=>{draft.agentSummaryDirty=true;draft.configDirty=true;try{draft.agentProposal=editProposalInput(draft.agentProposal,Number(input.dataset.summaryChange),input.value);}catch{}save();submit.disabled=true;summaryCheck.hidden=false;root.querySelector('.summary-status').textContent='Edits need checking. Recheck the summary before opening.';});
  summaryCheck.onclick=async()=>{let candidate;try{candidate=collectEditedProposal(draft.agentProposal,root);}catch(e){alertMessage(e.message);return;}lock();try{draft=acceptSetup(draft,await checked(candidate));if(draft.agent)draft.agent.proposal=null;save();message='Inputs checked. Review their updated effects below.';}catch(e){message=e.message;}busy=false;render(false);};}
 const agentButton=root.querySelector('#open-agent');if(agentButton)agentButton.onclick=()=>{capture();if(step===4&&(draft.agentSummaryDirty||draft.configDirty)){alertMessage('Recheck the summary edits before switching to the conversation.');return;}if(stageControls?.invalid()){alertMessage('Fix the highlighted settings before switching to the conversation.');return;}agentOpen=true;render();};
 root.querySelector('#show-library').onclick=()=>{try{capture();if(draft.name)save();showLibrary();}catch(e){alertMessage(e.message);}};
 root.querySelector('#previous').onclick=()=>{if(step===4&&(draft.agentSummaryDirty||draft.configDirty)){alertMessage('Recheck the summary edits before switching stages.');return;}if(stageControls?.invalid()){alertMessage('Fix the highlighted settings before going back.');return;}capture();step--;message='';save();render();};
 root.querySelectorAll('[data-edit-stage]').forEach(b=>b.onclick=()=>{if(draft.agentSummaryDirty||draft.configDirty){alertMessage('Recheck the summary edits before switching stages.');return;}step=Number(b.dataset.editStage);save();render();});
 root.querySelector('#setup-form').onsubmit=e=>{e.preventDefault();advance();};
 for(const key of ['name','purpose','region','asOf','seed']){const input=root.querySelector('#setup-'+key);if(input)input.oninput=()=>changed();}
 const retry=root.querySelector('#retry-config');if(retry)retry.onclick=()=>loadConfiguration();
}
function bindKpis(){root.querySelectorAll('[name="kpi"]').forEach(input=>input.onchange=()=>{const chosen=new Set(draft.kpis||[]);if(input.checked)chosen.add(input.value);else chosen.delete(input.value);if(chosen.size>12){input.checked=false;alertMessage('Watch up to twelve figures; the glossary explains them all.');return;}draft.kpis=[...chosen];input.closest('.kpi-chip')?.classList.toggle('is-on',input.checked);changed();});}
function open(s){if(isApp()&&s.execution==='local'&&!s.worldId)s.locked=false;library.update(s.id,{openedAt:new Date().toISOString()});location.href=s.worldId?'/world-map?world='+encodeURIComponent(s.worldId):studioURL(s,location.search);}
async function loadTwinDictionary(){if(twinDictionary)return;try{const r=await fetch(api+'/twin/dictionary');if(!r.ok)throw Error('KPI definitions could not load.');twinDictionary=await r.json();if(draft?.setupPath==='metrics'&&step===1)render(false);}catch(e){message=e.message;}}
try{library=new SimulationLibrary();packs=await fetchPackIndex();library.adoptPacks(packs);files=installShareFiles({api,library,onMessage:alertMessage,onImported:s=>{showLibrary();alertMessage(`Imported “${s.name}” (${handleLabel(s.handle)}). Open it to review its settings and start.`);}});if(query.get('edit')&&library.get(query.get('edit')))begin({...library.get(query.get('edit')),status:'draft',step:0});else if(location.hash.startsWith('#/setup/')&&library.get(decodeURIComponent(location.hash.slice(8))))begin(library.get(decodeURIComponent(location.hash.slice(8))));else if(location.hash==='#/new'||!library.list().length)begin();else showLibrary();}
catch(e){root.innerHTML=`<section class="library"><h1>Your simulations couldn’t open.</h1><p role="alert">${esc(e.message)}</p><button class="primary" onclick="location.reload()">Try again</button><p>Existing browser data has not been removed.</p></section>`;}
